package expo.modules.recognitioncpu;
import java.nio.file.*;
import java.util.*;

/** Read-only validation of bytes generated by the actual frozen preview-v3 camera constructor. */
public final class CameraOrientationRetainedInitializationChecks {
  static int checks;
  static void ok(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
  interface Work{void run()throws Exception;}
  static void no(Work work)throws Exception{boolean refused=false;try{work.run();}catch(IllegalArgumentException expected){refused=true;}ok(refused,"invalid/consumed profile must refuse");}
  static Path copyCamera(Path fixture,Path output,String name)throws Exception{
    Path parent=output.resolve(name);Path camera=parent.resolve(CameraOrientationPreviewRetained.CAMERA);Files.createDirectories(camera);
    for(String leaf:List.of("owner","refusals"))Files.copy(fixture.resolve(CameraOrientationPreviewRetained.CAMERA).resolve(leaf),camera.resolve(leaf));
    return parent;
  }
  static void refusedUnchanged(Path parent,CameraOrientationPreviewRetainedChecks.IO io)throws Exception{
    Map<String,String> before=CameraOrientationPreviewRetainedChecks.hashes(parent);
    no(()->CameraOrientationPreviewRetained.emptyClaims(parent.toFile(),io));
    ok(io.mutations==0&&before.equals(CameraOrientationPreviewRetainedChecks.hashes(parent)),"refusal cannot rewrite evidence");
  }
  public static void main(String[] args)throws Exception{
    Path parent=Path.of(args[0]);CameraOrientationPreviewRetainedChecks.IO io=new CameraOrientationPreviewRetainedChecks.IO();
    Path camera=parent.resolve(CameraOrientationPreviewRetained.CAMERA),run=parent.resolve(CameraOrientationPreviewRetained.ROOT);
    ok(Files.isDirectory(camera)&&!Files.exists(run),"actual v3 camera-only fixture required");
    Map<String,String> before=CameraOrientationPreviewRetainedChecks.hashes(parent);
    long metadata=CameraOrientationPreviewRetained.emptyClaims(parent.toFile(),io),actual=CameraOrientationPreviewRetainedChecks.size(camera);
    ok(metadata==actual,"charge exact existing camera metadata; absent run has no bytes");
    ok(io.mutations==0&&!Files.exists(run)&&before.equals(CameraOrientationPreviewRetainedChecks.hashes(parent)),"do not create historical run or mutate old evidence");
    ok(CameraOrientationPreviewRetained.CONSUMED_ALLOWANCE==64L*1024+14L*1024,"full old consumed fixture allowance unchanged");
    Path output=Path.of(args[1]);Files.createDirectories(output);
    for(String leaf:List.of("empty","owner.new")){
      Path p=copyCamera(parent,output,"run-"+leaf),r=p.resolve(CameraOrientationPreviewRetained.ROOT);Files.createDirectory(r);
      if(!leaf.equals("empty"))Files.write(r.resolve(leaf),new byte[]{1});
      refusedUnchanged(p,io);
    }
    for(CameraMatrixRecoveryPlan.Lane lane:List.of(CameraMatrixRecoveryPlan.Lane.RETAINED_PREVIEW_ORIENTATION_FIRST,CameraMatrixRecoveryPlan.Lane.RETAINED_PREVIEW_ORIENTATION_FINAL)){
      Path p=copyCamera(parent,output,"export-"+lane.name());Files.createDirectory(p.resolve(lane.root));refusedUnchanged(p,io);
    }
    for(String leaf:List.of("0120f4aa-9aeb-454e-b7ba-9640b94f4b8c.reservation","0120f4aa-9aeb-454e-b7ba-9640b94f4b8c.raw.jpg","unknown")){
      Path p=copyCamera(parent,output,"camera-"+leaf);Files.write(p.resolve(CameraOrientationPreviewRetained.CAMERA).resolve(leaf),new byte[]{1});refusedUnchanged(p,io);
    }
    Path wrong=copyCamera(parent,output,"wrong-owner");Path owner=wrong.resolve(CameraOrientationPreviewRetained.CAMERA).resolve("owner");byte[] raw=Files.readAllBytes(owner);raw[0]^=1;Files.write(owner,raw);refusedUnchanged(wrong,io);
    Path missing=output.resolve("missing-camera");Files.createDirectory(missing);refusedUnchanged(missing,io);
    System.out.println("CameraOrientationRetainedInitializationChecks assertions="+checks+"; actual frozen v3 constructor bytes + host IO; private phone roots unobserved");
  }
}
